SELECT toStartOfHour(time) AS hr, AVG(value_1) AS value_1, AVG(value_2) AS value_2, AVG(value_3) AS value_3, AVG(value_4) AS value_4 FROM (SELECT time, MAX(CASE WHEN metric_name = 'metric_0001' THEN CAST(value AS DOUBLE PRECISION) END) AS value_1, MAX(CASE WHEN metric_name = 'metric_0002' THEN CAST(value AS DOUBLE PRECISION) END) AS value_2, MAX(CASE WHEN metric_name = 'metric_0003' THEN CAST(value AS DOUBLE PRECISION) END) AS value_3, MAX(CASE WHEN metric_name = 'metric_0004' THEN CAST(value AS DOUBLE PRECISION) END) AS value_4 FROM eav100 WHERE metric_name IN ('metric_0001', 'metric_0002', 'metric_0003', 'metric_0004') GROUP BY time) s GROUP BY toStartOfHour(time) ORDER BY hr
